package com.bank.paging.repository;

import com.bank.paging.model.Txn;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.JpaRepository;

public interface TxnRepository extends JpaRepository<Txn, Long> {

    // Page: includes a count query (total elements / pages)
    Page<Txn> findByAccountId(String accountId, Pageable pageable);

    // Slice: no count query, cheaper, knows only hasNext()
    Slice<Txn> findByAccountIdOrderByCreatedAtDesc(String accountId, Pageable pageable);
}
