package com.bank.paging.service;

import com.bank.paging.model.*;
import com.bank.paging.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class StatementService {
    private final TxnRepository txnRepo;
    private final AccountRepository accountRepo;

    // Page: dashboard needs total count ("page 3 of 200")
    @Transactional(readOnly = true)
    public Page<Txn> page(String acct, int pageNo, int size) {
        Pageable p = PageRequest.of(pageNo, size,
                Sort.by(Sort.Direction.DESC, "createdAt").and(Sort.by("id")));
        Page<Txn> page = txnRepo.findByAccountId(acct, p);
        log.info("Page {}/{} total={}", pageNo, page.getTotalPages(), page.getTotalElements());
        return page;  // runs SELECT + COUNT
    }

    // Slice: infinite scroll, skip the count for speed
    @Transactional(readOnly = true)
    public Slice<Txn> slice(String acct, int pageNo, int size) {
        Pageable p = PageRequest.of(pageNo, size);
        Slice<Txn> slice = txnRepo.findByAccountIdOrderByCreatedAtDesc(acct, p);
        log.info("Slice page {} hasNext={}", pageNo, slice.hasNext());
        return slice;  // no COUNT; fetches size+1 internally
    }

    // Multi-column sort without pagination
    @Transactional(readOnly = true)
    public List<Account> byBalanceDesc() {
        Sort sort = Sort.by(Sort.Direction.DESC, "balance").and(Sort.by("id"));
        return accountRepo.findAll(sort);  // ORDER BY balance DESC, id ASC
    }
}
